import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(arr);

        Map<Integer, Long> ways = new HashMap<>();
        long total = 0;

        for (int i = 0; i < arr.length; i++) {
            long count = 1; // The tree consisting only of this root.

            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int rightValue = arr[i] / arr[j];
                    Long rightWays = ways.get(rightValue);

                    if (rightWays != null) {
                        count = (count + ways.get(arr[j]) * rightWays) % MOD;
                    }
                }
            }

            ways.put(arr[i], count);
            total = (total + count) % MOD;
        }

        return (int) total;
    }
}
