class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int roof = m * n;

        int[][] remaining = new int[m][n];
        for (int r = 0; r < m; r++) {
            remaining[r] = grid[r].clone();
        }

        boolean[] removed = new boolean[hits.length];
        for (int i = 0; i < hits.length; i++) {
            int r = hits[i][0];
            int c = hits[i][1];
            if (remaining[r][c] == 1) {
                removed[i] = true;
                remaining[r][c] = 0;
            }
        }

        DSU dsu = new DSU(roof + 1);
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (remaining[r][c] == 0) {
                    continue;
                }

                int id = r * n + c;
                if (r == 0) {
                    dsu.union(id, roof);
                }
                if (r > 0 && remaining[r - 1][c] == 1) {
                    dsu.union(id, id - n);
                }
                if (c > 0 && remaining[r][c - 1] == 1) {
                    dsu.union(id, id - 1);
                }
            }
        }

        int[] result = new int[hits.length];
        int[] directions = {-1, 0, 1, 0, -1};

        // Restore hits backward, measuring newly roof-connected bricks.
        for (int i = hits.length - 1; i >= 0; i--) {
            if (!removed[i]) {
                continue;
            }

            int r = hits[i][0];
            int c = hits[i][1];
            int id = r * n + c;
            int before = dsu.componentSize(roof);

            remaining[r][c] = 1;
            if (r == 0) {
                dsu.union(id, roof);
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + directions[d];
                int nc = c + directions[d + 1];

                if (nr >= 0 && nr < m && nc >= 0 && nc < n
                        && remaining[nr][nc] == 1) {
                    dsu.union(id, nr * n + nc);
                }
            }

            // Exclude the restored brick itself.
            result[i] = Math.max(0, dsu.componentSize(roof) - before - 1);
        }

        return result;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] size;

        DSU(int count) {
            parent = new int[count];
            size = new int[count];
            for (int i = 0; i < count; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (x != parent[x]) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }

            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int componentSize(int x) {
            return size[find(x)];
        }
    }
}
