    public boolean areOccurrencesEqual(String s) {
        int[] frequencies = new int[26];
        for (int i = 0; i < s.length(); i++) {
            frequencies[s.charAt(i) - 'a']++;
        }

        int expected = frequencies[s.charAt(0) - 'a'];
