class Solution {
    public int clumsy(int n) {
        if (n == 1) return 1;
        if (n == 2) return 2;
        if (n == 3) return 6;
        if (n == 4) return 7;

        // For n > 4, groups of four produce a repeating pattern.
        switch (n % 4) {
            case 0:
                return n + 1;
            case 1:
            case 2:
                return n + 2;
            default:
                return n - 1;
        }
    }
}
