class Solution {
    public int countCollisions(String directions) {
        int left = 0;
        int right = directions.length() - 1;

        // These cars leave the road without colliding.
        while (left <= right && directions.charAt(left) == 'L') {
            left++;
        }
        while (left <= right && directions.charAt(right) == 'R') {
            right--;
        }

        // Every remaining moving car contributes exactly one collision.
        int collisions = 0;
        for (int i = left; i <= right; i++) {
            if (directions.charAt(i) != 'S') {
                collisions++;
            }
        }

        return collisions;
    }
}
