class Solution {
    public int countMaxOrSubsets(int[] nums) {
        int maxOr = 0;
        for (int num : nums) {
            maxOr |= num;
        }
        return count(nums, 0, 0, maxOr);
    }

    private int count(int[] nums, int index, int currentOr, int maxOr) {
        if (currentOr == maxOr) {
            return 1 << (nums.length - index);
        }
        if (index == nums.length) {
            return 0;
        }

        return count(nums, index + 1, currentOr | nums[index], maxOr)
             + count(nums, index + 1, currentOr, maxOr);
    }
}
