class CustomStack {
    private final int[] stack;
    private final int[] pending;
    private int size;

    public CustomStack(int maxSize) {
        stack = new int[maxSize];
        pending = new int[maxSize];
        size = 0;
    }

    public void push(int x) {
        if (size == stack.length) {
            return;
        }
        stack[size] = x;
        pending[size] = 0;
        size++;
    }

    public int pop() {
        if (size == 0) {
            return -1;
        }

        int top = --size;
        int result = stack[top] + pending[top];

        if (top > 0) {
            pending[top - 1] += pending[top];
        }
        pending[top] = 0;

        return result;
    }

    public void increment(int k, int val) {
        int index = Math.min(k, size) - 1;
        if (index >= 0) {
            pending[index] += val;
        }
    }
}
