        for (int i = 0; i < n && n - i > answer; i++) {
            Map<Long, Integer> counts = new HashMap<>();

            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                int divisor = gcd(Math.abs(dx), Math.abs(dy));
                dx /= divisor;
                dy /= divisor;

                // Give opposite directions on the same line one representation.
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }

                long slope = ((long) dx << 32) | (dy & 0xffffffffL);
                int count = counts.getOrDefault(slope, 0) + 1;
                counts.put(slope, count);

                answer = Math.max(answer, count + 1);
            }
        }

        return answer;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
