class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = students[0].length;
        int[][] scores = new int[m][m];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        scores[i][j]++;
                    }
                }
            }
        }

        // dp[mask] assigns the first bitCount(mask) students to these mentors.
        int[] dp = new int[1 << m];
        for (int mask = 1; mask < dp.length; mask++) {
            int student = Integer.bitCount(mask) - 1;
            for (int mentor = 0; mentor < m; mentor++) {
                int bit = 1 << mentor;
                if ((mask & bit) != 0) {
                    dp[mask] = Math.max(
                        dp[mask],
                        dp[mask ^ bit] + scores[student][mentor]
                    );
                }
            }
        }

        return dp[dp.length - 1];
    }
}
