class Solution {
    public int maxEqualFreq(int[] nums) {
        int[] count = new int[100001];
        int[] frequencyCount = new int[nums.length + 1];
        int maxFrequency = 0;
        int answer = 0;

        for (int i = 0; i < nums.length; i++) {
            int value = nums[i];
            int oldFrequency = count[value];

            if (oldFrequency > 0) {
                frequencyCount[oldFrequency]--;
            }

            int newFrequency = ++count[value];
            frequencyCount[newFrequency]++;
            maxFrequency = Math.max(maxFrequency, newFrequency);

            int length = i + 1;

            // All values appear once.
            boolean valid = maxFrequency == 1;

            // Remove the only value that appears once.
            valid |= frequencyCount[1] == 1
                    && frequencyCount[maxFrequency] * maxFrequency == length - 1;

            // Remove one occurrence of the only most frequent value.
            valid |= frequencyCount[maxFrequency] == 1
                    && frequencyCount[maxFrequency - 1] * (maxFrequency - 1)
                    + maxFrequency == length;

            if (valid) {
                answer = length;
            }
        }

        return answer;
    }
}
