class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int states = 1 << n;

        int[] studentCount = new int[states];
        for (int mask = 0; mask < states; mask++) {
            studentCount[mask] = Integer.bitCount(mask);
        }

        int[] dp = new int[states];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int row = 0; row < m; row++) {
            int available = 0;
            for (int col = 0; col < n; col++) {
                if (seats[row][col] == '.') {
                    available |= 1 << col;
                }
            }

            int[] next = new int[states];
            java.util.Arrays.fill(next, -1);

            for (int mask = 0; mask < states; mask++) {
                // Use only working seats, with no horizontal neighbors.
                if ((mask & available) != mask ||
                    (mask & (mask << 1)) != 0) {
                    continue;
                }

                for (int previous = 0; previous < states; previous++) {
                    if (dp[previous] == -1) {
                        continue;
                    }

                    // Exclude diagonal neighbors in the preceding row.
                    if ((mask & (previous << 1)) == 0 &&
                        (mask & (previous >> 1)) == 0) {
                        next[mask] = Math.max(
                            next[mask],
                            dp[previous] + studentCount[mask]
                        );
                    }
                }
            }

            dp = next;
        }

        int answer = 0;
        for (int value : dp) {
            answer = Math.max(answer, value);
        }
        return answer;
    }
}
