class Solution {
    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int bestFirst = 0;
        int bestSecond = 0;
        int answer = 0;

        for (int end = firstLen + secondLen; end <= n; end++) {
            // Best firstLen window entirely before the current secondLen window.
            bestFirst = Math.max(bestFirst,
                    prefix[end - secondLen] - prefix[end - secondLen - firstLen]);
            answer = Math.max(answer,
                    bestFirst + prefix[end] - prefix[end - secondLen]);

            // Best secondLen window entirely before the current firstLen window.
            bestSecond = Math.max(bestSecond,
                    prefix[end - firstLen] - prefix[end - firstLen - secondLen]);
            answer = Math.max(answer,
                    bestSecond + prefix[end] - prefix[end - firstLen]);
        }

        return answer;
    }
}
