class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) {
            return -1;
        }

        int low = Integer.MAX_VALUE;
        int high = 0;
        for (int day : bloomDay) {
            low = Math.min(low, day);
            high = Math.max(high, day);
        }

        while (low < high) {
            int mid = low + (high - low) / 2;
            int bouquets = 0;
            int consecutive = 0;

            for (int day : bloomDay) {
                if (day <= mid) {
                    consecutive++;
                    if (consecutive == k) {
                        bouquets++;
                        consecutive = 0;
                        if (bouquets == m) {
                            break;
                        }
                    }
                } else {
                    consecutive = 0;
                }
            }

            if (bouquets >= m) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }
}
