class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }

        if (sum % k != 0) {
            return false;
        }

        int target = sum / k;
        for (int num : nums) {
            if (num > target) {
                return false;
            }
        }

        int states = 1 << nums.length;

        // dp[mask] is the current subset sum, or -1 if unreachable.
        int[] dp = new int[states];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < states; mask++) {
            if (dp[mask] == -1) {
                continue;
            }

            for (int i = 0; i < nums.length; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }

                int nextSum = dp[mask] + nums[i];
                if (nextSum > target) {
                    continue;
                }

                int nextMask = mask | (1 << i);
                dp[nextMask] = nextSum % target;
            }
        }

        return dp[states - 1] == 0;
    }
}
