class Solution {
    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        boolean[] result = new boolean[requests.length];

        for (int i = 0; i < requests.length; i++) {
            int rootU = find(parent, requests[i][0]);
            int rootV = find(parent, requests[i][1]);

            if (rootU == rootV) {
                result[i] = true;
                continue;
            }

            boolean allowed = true;
            for (int[] restriction : restrictions) {
                int rootX = find(parent, restriction[0]);
                int rootY = find(parent, restriction[1]);

                if ((rootX == rootU && rootY == rootV)
                        || (rootX == rootV && rootY == rootU)) {
                    allowed = false;
                    break;
                }
            }

            if (allowed) {
                result[i] = true;
                if (size[rootU] < size[rootV]) {
                    parent[rootU] = rootV;
                    size[rootV] += size[rootU];
                } else {
                    parent[rootV] = rootU;
                    size[rootU] += size[rootV];
                }
            }
        }

        return result;
    }

    private int find(int[] parent, int person) {
        while (parent[person] != person) {
            parent[person] = parent[parent[person]];
            person = parent[person];
        }
        return person;
    }
}
