class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int total = 4 * n * n;
        int[] parent = new int[total];
        int[] rank = new int[total];

        for (int i = 0; i < total; i++) {
            parent[i] = i;
        }

        int regions = total;

        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                // Triangle indices: top, right, bottom, left.
                int base = 4 * (row * n + col);
                char ch = grid[row].charAt(col);

                if (ch != '/') {
                    regions -= union(parent, rank, base, base + 1);
                    regions -= union(parent, rank, base + 2, base + 3);
                }

                if (ch != '\\') {
                    regions -= union(parent, rank, base, base + 3);
                    regions -= union(parent, rank, base + 1, base + 2);
                }

                if (col + 1 < n) {
                    regions -= union(parent, rank, base + 1, base + 7);
                }

                if (row + 1 < n) {
                    regions -= union(parent, rank, base + 2, base + 4 * n);
                }
            }
        }

        return regions;
    }

    private int find(int[] parent, int node) {
        if (parent[node] != node) {
            parent[node] = find(parent, parent[node]);
        }
        return parent[node];
    }

    private int union(int[] parent, int[] rank, int a, int b) {
        int rootA = find(parent, a);
        int rootB = find(parent, b);

        if (rootA == rootB) {
            return 0;
        }

        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }

        return 1;
    }
}
