import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        List<String> result = new ArrayList<>();
        remove(s, 0, 0, '(', ')', result);
        return result;
    }

    private void remove(String s, int scanStart, int removalStart,
                        char open, char close, List<String> result) {
        int balance = 0;

        for (int i = scanStart; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == open) {
                balance++;
            } else if (c == close) {
                balance--;
            }

            if (balance >= 0) {
                continue;
            }

            for (int j = removalStart; j <= i; j++) {
                if (s.charAt(j) == close
                        && (j == removalStart || s.charAt(j - 1) != close)) {
                    String next = s.substring(0, j) + s.substring(j + 1);
                    remove(next, i, j, open, close, result);
                }
            }
            return;
        }

        String reversed = new StringBuilder(s).reverse().toString();
        if (open == '(') {
            remove(reversed, 0, 0, ')', '(', result);
        } else {
            result.add(reversed);
        }
    }
}
