    private char[] first;
    private char[] second;
    private byte[][][] memo;

    public boolean isScramble(String s1, String s2) {
        if (s1.length() != s2.length()) {
            return false;
        }
        if (s1.equals(s2)) {
            return true;
        }

        int n = s1.length();
        first = s1.toCharArray();
        second = s2.toCharArray();
        memo = new byte[n][n][n + 1];

        return solve(0, 0, n);
    }

    private boolean solve(int i, int j, int length) {
        if (memo[i][j][length] != 0) {
            return memo[i][j][length] == 1;
        }

        int[] counts = new int[26];
        boolean identical = true;

        for (int k = 0; k < length; k++) {
            counts[first[i + k] - 'a']++;
            counts[second[j + k] - 'a']--;
            if (first[i + k] != second[j + k]) {
                identical = false;
            }
        }

        if (identical) {
            memo[i][j][length] = 1;
            return true;
        }

        for (int count : counts) {
            if (count != 0) {
                memo[i][j][length] = -1;
                return false;
            }
        }

        for (int split = 1; split < length; split++) {
            // Keep the two parts in their original order.
            if (solve(i, j, split)
                    && solve(i + split, j + split, length - split)) {
                memo[i][j][length] = 1;
                return true;
            }

            // Swap the two parts.
            if (solve(i, j + length - split, split)
                    && solve(i + split, j, length - split)) {
                memo[i][j][length] = 1;
                return true;
            }
        }

        memo[i][j][length] = -1;
        return false;
    }
}
