import java.util.Comparator;
import java.util.TreeSet;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        Comparator<Integer> order = (a, b) -> {
            int comparison = Integer.compare(nums[a], nums[b]);
            return comparison != 0 ? comparison : Integer.compare(a, b);
        };

        TreeSet<Integer> lower = new TreeSet<>(order);
        TreeSet<Integer> upper = new TreeSet<>(order);
        double[] result = new double[nums.length - k + 1];

        for (int i = 0; i < nums.length; i++) {
            if (lower.isEmpty() || order.compare(i, lower.last()) <= 0) {
                lower.add(i);
            } else {
                upper.add(i);
            }

            if (i >= k) {
                int outgoing = i - k;
                if (!lower.remove(outgoing)) {
                    upper.remove(outgoing);
                }
            }

            // Keep the smaller half in lower, with one extra element if odd.
            while (lower.size() > upper.size() + 1) {
                upper.add(lower.pollLast());
            }
            while (lower.size() < upper.size()) {
                lower.add(upper.pollFirst());
            }

            if (i >= k - 1) {
                if ((k & 1) == 1) {
                    result[i - k + 1] = nums[lower.last()];
                } else {
                    result[i - k + 1] =
                            ((long) nums[lower.last()] + nums[upper.first()]) / 2.0;
                }
            }
        }

        return result;
    }
}
