class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int count = 0;
        int r = rStart;
        int c = cStart;

        result[count][0] = r;
        result[count++][1] = c;

        int[] dr = {0, 1, 0, -1};
        int[] dc = {1, 0, -1, 0};
        int direction = 0;
        int length = 1;

        while (count < total) {
            for (int turn = 0; turn < 2; turn++) {
                for (int step = 0; step < length; step++) {
                    r += dr[direction];
                    c += dc[direction];

                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result[count][0] = r;
                        result[count++][1] = c;

                        if (count == total) {
                            return result;
                        }
                    }
                }
                direction = (direction + 1) % 4;
            }
            length++;
        }

        return result;
    }
}
