    public int splitArray(int[] nums, int k) {
        int low = 0;
        int high = 0;

        for (int num : nums) {
            low = Math.max(low, num);
            high += num;
        }

        while (low < high) {
            int limit = low + (high - low) / 2;
            int parts = 1;
            int sum = 0;

            for (int num : nums) {
                if (sum + num > limit) {
                    parts++;
