    private int[][][][] memo;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new int[n + 1][n + 1][n + 1][];
        return solve(n, firstPlayer, secondPlayer);
    }

    private int[] solve(int n, int first, int second) {
        if (first + second == n + 1) {
            return new int[]{1, 1};
        }

        // Reflect the row to merge symmetric states.
        if (first + second > n + 1) {
            int reflectedFirst = n + 1 - second;
            second = n + 1 - first;
            first = reflectedFirst;
        }

        if (memo[n][first][second] != null) {
            return memo[n][first][second];
        }

        int nextN = (n + 1) / 2;

        // reachable[a][b]: a winners precede first, b winners precede second.
        boolean[][] reachable = new boolean[nextN + 1][nextN + 1];
        reachable[0][0] = true;
        int processed = 0;

        for (int left = 1, right = n; left <= right; left++, right--) {
            int[] possibleWinners;
            if (left == first || left == second || left == right) {
                possibleWinners = new int[]{left};
            } else if (right == first || right == second) {
                possibleWinners = new int[]{right};
            } else {
                possibleWinners = new int[]{left, right};
            }

            boolean[][] next = new boolean[nextN + 1][nextN + 1];
            for (int winner : possibleWinners) {
                int beforeFirst = winner < first ? 1 : 0;
                int beforeSecond = winner < second ? 1 : 0;

                for (int a = 0; a <= processed; a++) {
                    for (int b = a; b <= processed; b++) {
                        if (reachable[a][b]) {
                            next[a + beforeFirst][b + beforeSecond] = true;
                        }
                    }
                }
            }

            reachable = next;
            processed++;
        }

        int earliest = Integer.MAX_VALUE;
        int latest = 0;

        for (int a = 0; a < nextN; a++) {
            for (int b = a + 1; b < nextN; b++) {
                if (reachable[a][b]) {
                    int[] result = solve(nextN, a + 1, b + 1);
                    earliest = Math.min(earliest, result[0] + 1);
                    latest = Math.max(latest, result[1] + 1);
                }
            }
        }

        return memo[n][first][second] = new int[]{earliest, latest};
    }
}
