class Solution {
    private String[] words;
    private String result;
    private int[] digit;
    private boolean[] used;
    private boolean[] nonZero;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        digit = new int[26];
        java.util.Arrays.fill(digit, -1);
        used = new boolean[10];
        nonZero = new boolean[26];

        int maxLength = 0;
        for (String word : words) {
            maxLength = Math.max(maxLength, word.length());
            if (word.length() > 1) {
                nonZero[word.charAt(0) - 'A'] = true;
            }
        }

        if (result.length() < maxLength || result.length() > maxLength + 1) {
            return false;
        }
        if (result.length() > 1) {
            nonZero[result.charAt(0) - 'A'] = true;
        }

        return search(0, 0, 0);
    }

    // Process each column from right to left, carrying its sum forward.
    private boolean search(int column, int row, int sum) {
        if (column == result.length()) {
            return sum == 0;
        }

        if (row < words.length) {
            String word = words[row];
            if (column >= word.length()) {
                return search(column, row + 1, sum);
            }

            int letter = word.charAt(word.length() - 1 - column) - 'A';
            if (digit[letter] != -1) {
                return search(column, row + 1, sum + digit[letter]);
            }

            for (int d = 0; d <= 9; d++) {
                if (used[d] || (d == 0 && nonZero[letter])) {
                    continue;
                }

                digit[letter] = d;
                used[d] = true;

                if (search(column, row + 1, sum + d)) {
                    return true;
                }

                used[d] = false;
                digit[letter] = -1;
            }
            return false;
        }

        int letter = result.charAt(result.length() - 1 - column) - 'A';
        int required = sum % 10;
        int carry = sum / 10;

        if (digit[letter] != -1) {
            return digit[letter] == required && search(column + 1, 0, carry);
        }

        if (used[required] || (required == 0 && nonZero[letter])) {
            return false;
        }

        digit[letter] = required;
        used[required] = true;

        if (search(column + 1, 0, carry)) {
            return true;
        }

        used[required] = false;
        digit[letter] = -1;
        return false;
    }
}
